{
  "correction_rules": [
    "Reduce forecast overshoots following strong positive sentiment spikes (e.g., sentiment > 0.5) by 5-15% to avoid overreaction.",
    "Adjust downward for persistent negative sentiment (sentiment < -0.5) by 3-8% to account for risk aversion or market cooling.",
    "Apply mean reversion bias: if forecast deviates > 10% from recent 7-day average, correct toward historical mean.",
    "Correct for lagged responses: if true outcome is > 2 days after forecast peak, reduce forecast by 2-5% per day to reflect delayed market reaction.",
    "When sentiment is neutral (±0.25), apply a 2% downward bias to avoid overconfidence in flat periods.",
    "For high volatility periods (e.g., > 15% 30-day range), reduce forecast variance by 10-20% to reflect uncertainty."
  ]
}
